router.post('/distributor/consignment-returns',authMiddleware,distributor,async(req:AuthedRequest,res)=>{
 const {request_date,notes,items}=req.body||{};if(!isDateOnly(request_date||'')||!Array.isArray(items)||!items.length||items.length>100||String(notes||'').length>1000)return res.status(400).json({ok:false,message:'Tanggal, rincian barang, dan catatan retur harus valid.'});
 const conn=await pool.getConnection();try{await conn.beginTransaction();const distributorId=req.identity!.distributorId!;const [loc]=await conn.execute<RowDataPacket[]>(`SELECT id FROM stock_locations WHERE distributor_id=? AND location_type='DISTRIBUTOR' AND is_active=1 LIMIT 1 FOR UPDATE`,[distributorId]);if(!loc.length)throw new Error('Lokasi stok distributor tidak ditemukan.');const locationId=Number(loc[0].id),requestCode=code('RET');const seen=new Set<string>();const [h]=await conn.execute<ResultSetHeader>(`INSERT INTO distributor_consignment_return_requests (request_code,distributor_id,request_date,status,notes,submitted_by_user_id) VALUES (?,?,?,'PENDING',?,?)`,[requestCode,distributorId,request_date,notes||null,req.identity!.id]);const requestId=Number(h.insertId);
  for(const raw of items){const productId=Number(raw.product_id),qty=Number(raw.quantity),condition=String(raw.item_condition||'').toUpperCase();const key=productId+':'+condition;if(!validConsignmentReturnLine(productId,qty,condition)||seen.has(key))throw new Error('Rincian retur tidak valid atau produk/ kondisi duplikat.');seen.add(key);const [products]=await conn.execute<RowDataPacket[]>(`SELECT id,product_name,COALESCE(average_cost,purchase_cost,0) unit_cost,COALESCE((SELECT SUM(cdi.quantity*cdi.distributor_price_snapshot)/NULLIF(SUM(cdi.quantity),0) FROM consignment_delivery_items cdi JOIN consignment_deliveries cd ON cd.id=cdi.delivery_id WHERE cd.distributor_id=? AND cd.status='POSTED' AND cdi.product_id=products.id),distributor_price,0) distributor_price_snapshot FROM products WHERE id=? AND is_active=1 FOR UPDATE`,[distributorId,productId]);if(!products.length)throw new Error('Produk tidak aktif/tidak ditemukan.');const [available]=await conn.execute<RowDataPacket[]>(`SELECT COALESCE(SUM(CASE WHEN to_location_id=? THEN quantity ELSE 0 END),0)-COALESCE(SUM(CASE WHEN from_location_id=? THEN quantity ELSE 0 END),0)-COALESCE((SELECT SUM(i.quantity_sold) FROM distributor_sales_report_items i JOIN distributor_sales_reports r ON r.id=i.report_id WHERE r.distributor_id=? AND r.status='SUBMITTED' AND i.product_id=?),0)-COALESCE((SELECT SUM(ri.quantity) FROM distributor_consignment_return_request_items ri JOIN distributor_consignment_return_requests rr ON rr.id=ri.request_id WHERE rr.distributor_id=? AND rr.status='PENDING' AND ri.product_id=?),0) available_qty FROM stock_movements WHERE product_id=? AND (to_location_id=? OR from_location_id=?)`,[locationId,locationId,distributorId,productId,distributorId,productId,productId,locationId,locationId]);if(!consignmentReturnQtyWithinAvailable(Number(available[0]?.available_qty||0),qty))throw new Error(`Retur ${products[0].product_name} melebihi stok titipan yang tersedia setelah reservasi laporan penjualan dan retur pending.`);await conn.execute(`INSERT INTO distributor_consignment_return_request_items (request_id,product_id,product_name_snapshot,quantity,item_condition,unit_cost_snapshot,distributor_price_snapshot) VALUES (?,?,?,?,?,?,?)`,[requestId,productId,products[0].product_name,qty,condition,Number(products[0].unit_cost||0),Number(products[0].distributor_price_snapshot||0)]);}
  await conn.execute(`INSERT INTO audit_logs (user_id,action,entity_type,entity_id,description) VALUES (?,'SUBMIT','CONSIGNMENT_RETURN_REQUEST',?,?)`,[req.identity!.id,requestId,`Distributor ${distributorId} mengajukan retur titipan; belum ada perpindahan stok`]);await conn.commit();return res.status(201).json({ok:true,request:{id:requestId,request_code:requestCode,status:'PENDING'},message:'Permohonan retur terkirim dan menunggu persetujuan pemilik.'});
 }catch(e){await conn.rollback();return res.status(400).json({ok:false,message:e instanceof Error?e.message:'Gagal mengajukan retur titipan.'});}finally{conn.release();}
});
router.get('/admin/consignment-returns',authMiddleware,ownerMiddleware,async(_req,res)=>{try{const [rows]=await pool.query<RowDataPacket[]>(`SELECT r.*,d.distributor_name,COALESCE(x.total_items,0) item_count,COALESCE(x.total_qty,0) total_qty FROM distributor_consignment_return_requests r JOIN distributors d ON d.id=r.distributor_id LEFT JOIN (SELECT request_id,COUNT(*) total_items,SUM(quantity) total_qty FROM distributor_consignment_return_request_items GROUP BY request_id) x ON x.request_id=r.id ORDER BY r.created_at DESC`);return res.json({ok:true,requests:rows});}catch(e){return res.status(500).json({ok:false,message:e instanceof Error?e.message:'Gagal memuat permohonan retur.'});}});
router.get('/admin/consignment-returns/:id',authMiddleware,ownerMiddleware,async(req,res)=>{const id=Number(req.params.id);if(!Number.isInteger(id)||id<=0)return res.status(400).json({ok:false,message:'ID retur tidak valid.'});try{const [heads]=await pool.execute<RowDataPacket[]>(`SELECT r.*,d.distributor_name FROM distributor_consignment_return_requests r JOIN distributors d ON d.id=r.distributor_id WHERE r.id=?`,[id]);if(!heads.length)return res.status(404).json({ok:false,message:'Permohonan retur tidak ditemukan.'});const [items]=await pool.execute<RowDataPacket[]>(`SELECT * FROM distributor_consignment_return_request_items WHERE request_id=? ORDER BY id`,[id]);return res.json({ok:true,request:heads[0],items});}catch(e){return res.status(500).json({ok:false,message:e instanceof Error?e.message:'Gagal memuat detail retur.'});}});
router.post('/admin/consignment-returns/:id/reject',authMiddleware,ownerMiddleware,async(req:AuthedRequest,res)=>{const id=Number(req.params.id),reason=String(req.body?.reason||'').trim();if(!Number.isInteger(id)||id<=0||!reason||reason.length>1000)return res.status(400).json({ok:false,message:'ID dan alasan penolakan (maksimal 1000 karakter) wajib diisi.'});const conn=await pool.getConnection();try{await conn.beginTransaction();const [rows]=await conn.execute<RowDataPacket[]>(`SELECT * FROM distributor_consignment_return_requests WHERE id=? AND status='PENDING' FOR UPDATE`,[id]);if(!rows.length)throw new Error('Permohonan tidak ditemukan atau sudah diproses.');await conn.execute(`UPDATE distributor_consignment_return_requests SET status='REJECTED',reviewed_by_user_id=?,reviewed_at=CURRENT_TIMESTAMP,rejection_reason=? WHERE id=? AND status='PENDING'`,[req.identity!.id,reason,id]);await conn.execute(`INSERT INTO audit_logs (user_id,action,entity_type,entity_id,description) VALUES (?,'REJECT','CONSIGNMENT_RETURN_REQUEST',?,?)`,[req.identity!.id,id,reason]);await conn.commit();return res.json({ok:true,message:'Permohonan retur ditolak.'});}catch(e){await conn.rollback();return res.status(400).json({ok:false,message:e instanceof Error?e.message:'Gagal menolak retur.'});}finally{conn.release();}});
router.post('/admin/consignment-returns/:id/approve',authMiddleware,ownerMiddleware,async(req:AuthedRequest,res)=>{const id=Number(req.params.id);if(!Number.isInteger(id)||id<=0)return res.status(400).json({ok:false,message:'ID retur tidak valid.'});const conn=await pool.getConnection();try{await conn.beginTransaction();const [requests]=await conn.execute<RowDataPacket[]>(`SELECT * FROM distributor_consignment_return_requests WHERE id=? AND status='PENDING' FOR UPDATE`,[id]);if(!requests.length)throw new Error('Permohonan tidak ditemukan atau sudah diproses.');const request=requests[0];const [locs]=await conn.execute<RowDataPacket[]>(`SELECT id FROM stock_locations WHERE distributor_id=? AND location_type='DISTRIBUTOR' AND is_active=1 LIMIT 1 FOR UPDATE`,[request.distributor_id]);if(!locs.length)throw new Error('Lokasi distributor tidak ditemukan.');const distributorLocation=Number(locs[0].id);const [items]=await conn.execute<RowDataPacket[]>(`SELECT * FROM distributor_consignment_return_request_items WHERE request_id=? ORDER BY product_id,item_condition FOR UPDATE`,[id]);if(!items.length)throw new Error('Permohonan kosong.');const [warehouse]=await conn.execute<RowDataPacket[]>(`SELECT id FROM stock_locations WHERE location_type='WAREHOUSE' AND is_active=1 ORDER BY id FOR UPDATE`);if(warehouse.length!==1)throw new Error('Harus tersedia tepat satu gudang aktif.');const [damaged]=await conn.execute<RowDataPacket[]>(`SELECT id FROM stock_locations WHERE location_type='DAMAGED' AND is_active=1 ORDER BY id LIMIT 1 FOR UPDATE`);const cumulativeReturnQty=new Map<number,number>();for(const item of items){const productId=Number(item.product_id),qty=Number(item.quantity),alreadyRequested=cumulativeReturnQty.get(productId)||0;const [ledger]=await conn.execute<RowDataPacket[]>(`SELECT COALESCE(SUM(CASE WHEN to_location_id=? THEN quantity ELSE 0 END),0)-COALESCE(SUM(CASE WHEN from_location_id=? THEN quantity ELSE 0 END),0)-COALESCE((SELECT SUM(i.quantity_sold) FROM distributor_sales_report_items i JOIN distributor_sales_reports r ON r.id=i.report_id WHERE r.distributor_id=? AND r.status='SUBMITTED' AND i.product_id=?),0)-COALESCE((SELECT SUM(ri.quantity) FROM distributor_consignment_return_request_items ri JOIN distributor_consignment_return_requests rr ON rr.id=ri.request_id WHERE rr.distributor_id=? AND rr.status='PENDING' AND rr.id<>? AND ri.product_id=?),0) available_qty FROM stock_movements WHERE product_id=? AND (to_location_id=? OR from_location_id=?)`,[distributorLocation,distributorLocation,request.distributor_id,productId,request.distributor_id,id,productId,productId,distributorLocation,distributorLocation]);if(!consignmentReturnQtyWithinAvailable(Number(ledger[0]?.available_qty||0),qty,alreadyRequested))throw new Error(`Stok ${item.product_name_snapshot} tidak mencukupi untuk persetujuan; periksa laporan penjualan pending dan retur lain.`);const toLocation=String(item.item_condition)==='DAMAGED'?Number(damaged[0]?.id||0):Number(warehouse[0].id);if(!toLocation)throw new Error('Lokasi barang rusak belum tersedia.');await conn.execute(`INSERT INTO stock_movements (movement_code,product_id,from_location_id,to_location_id,movement_type,quantity,unit_cost,reference_type,reference_id,note,created_by_user_id) VALUES (?,?,?,?,'CONSIGNMENT_RETURN',?,?,'CONSIGNMENT_RETURN_REQUEST',?,?,?)`,[`RET-${id}-${productId}-${String(item.item_condition)}`,productId,distributorLocation,toLocation,qty,Number(item.unit_cost_snapshot||0),id,`Retur titipan ${request.request_code} (${item.item_condition})`,req.identity!.id]);cumulativeReturnQty.set(productId,alreadyRequested+qty);}
 await conn.execute(`UPDATE distributor_consignment_return_requests SET status='APPROVED',reviewed_by_user_id=?,reviewed_at=CURRENT_TIMESTAMP,posted_at=CURRENT_TIMESTAMP WHERE id=? AND status='PENDING'`,[req.identity!.id,id]);await conn.execute(`INSERT INTO audit_logs (user_id,action,entity_type,entity_id,description) VALUES (?,'APPROVE_AND_POST','CONSIGNMENT_RETURN_REQUEST',?,?)`,[req.identity!.id,id,`Retur titipan ${request.request_code} diposting; stok good ke gudang dan damaged ke lokasi rusak; tidak ada refund otomatis`]);await conn.commit();return res.json({ok:true,message:'Retur disetujui dan perpindahan stok diposting satu kali.'});}catch(e){await conn.rollback();return res.status(400).json({ok:false,message:e instanceof Error?e.message:'Gagal menyetujui retur.'});}finally{conn.release();}});
router.get('/distributor/receivable-notes',authMiddleware,distributor,async(req:AuthedRequest,res)=>{try{const id=req.identity!.distributorId;const [rows]=await pool.execute<RowDataPacket[]>(`SELECT r.id,r.report_code,r.invoice_code,r.report_date,r.due_date,COALESCE(s.sales_total,0) sales_total,COALESCE(ret.return_total,0) return_total,COALESCE(paid.paid_total,0) paid_total,GREATEST(0,ROUND(COALESCE(s.sales_total,0)-COALESCE(ret.return_total,0)-COALESCE(paid.paid_total,0),2)) outstanding,CASE WHEN GREATEST(0,ROUND(COALESCE(s.sales_total,0)-COALESCE(ret.return_total,0)-COALESCE(paid.paid_total,0),2))<=0.01 THEN 'PAID' WHEN COALESCE(paid.paid_total,0)>0.01 THEN 'PARTIAL' ELSE 'UNPAID' END payment_status FROM distributor_sales_reports r LEFT JOIN (SELECT report_id,SUM(line_total) sales_total FROM distributor_sales_report_items GROUP BY report_id) s ON s.report_id=r.id LEFT JOIN (SELECT sales_report_id,SUM(total) return_total FROM distributor_sales_returns WHERE status='POSTED' GROUP BY sales_report_id) ret ON ret.sales_report_id=r.id LEFT JOIN (SELECT a.sales_report_id,SUM(a.allocated_amount) paid_total FROM distributor_payment_allocations a JOIN distributor_payment_submissions p ON p.id=a.payment_submission_id AND p.status='VERIFIED' GROUP BY a.sales_report_id) paid ON paid.sales_report_id=r.id WHERE r.distributor_id=? AND r.status='APPROVED' ORDER BY r.report_date DESC,r.id DESC`,[id]);return res.json({ok:true,notes:rows});}catch(e){return res.status(500).json({ok:false,message:e instanceof Error?e.message:'Gagal memuat rincian piutang per nota.'});}});
router.get('/distributor/receivable-notes/:id/allocations',authMiddleware,distributor,async(req:AuthedRequest,res)=>{const id=Number(req.params.id);if(!Number.isInteger(id)||id<=0)return res.status(400).json({ok:false,message:'ID nota tidak valid.'});try{const [notes]=await pool.execute<RowDataPacket[]>(`SELECT id,report_code,invoice_code FROM distributor_sales_reports WHERE id=? AND distributor_id=? AND status='APPROVED'`,[id,req.identity!.distributorId]);if(!notes.length)return res.status(404).json({ok:false,message:'Nota tidak ditemukan.'});const [rows]=await pool.execute<RowDataPacket[]>(`SELECT p.id,p.submission_code,p.payment_date,p.amount,p.payment_method,p.status,a.allocated_amount,p.proof_reference FROM distributor_payment_allocations a JOIN distributor_payment_submissions p ON p.id=a.payment_submission_id WHERE a.sales_report_id=? AND p.distributor_id=? AND p.status='VERIFIED' ORDER BY p.payment_date,p.id`,[id,req.identity!.distributorId]);return res.json({ok:true,report:notes[0],allocations:rows});}catch(e){return res.status(500).json({ok:false,message:e instanceof Error?e.message:'Gagal memuat alokasi pembayaran.'});}});
router.get('/distributor/summary',authMiddleware,distributor,async(req:AuthedRequest,res)=>{const id=req.identity!.distributorId;try{const [sales]=await pool.execute<RowDataPacket[]>(`SELECT COALESCE(SUM(i.line_total),0)-COALESCE((SELECT SUM(x.total) FROM distributor_sales_returns x WHERE x.distributor_id=? AND x.status='POSTED'),0) sales_total FROM distributor_sales_reports r JOIN distributor_sales_report_items i ON i.report_id=r.id WHERE r.distributor_id=? AND r.status='APPROVED'`,[id,id]);const [payments]=await pool.execute<RowDataPacket[]>(`SELECT COALESCE(SUM(a.allocated_amount),0) paid_total FROM distributor_payment_allocations a JOIN distributor_payment_submissions p ON p.id=a.payment_submission_id WHERE p.distributor_id=? AND p.status='VERIFIED'`,[id]);const [unapplied]=await pool.execute<RowDataPacket[]>(`SELECT COALESCE(SUM(unapplied_amount),0) unapplied_total FROM distributor_payment_submissions WHERE distributor_id=? AND status='VERIFIED'`,[id]);const [pendingPayment]=await pool.execute<RowDataPacket[]>(`SELECT COALESCE(SUM(amount),0) pending_total,COUNT(*) pending_count FROM distributor_payment_submissions WHERE distributor_id=? AND status='PENDING'`,[id]);const [pendingSales]=await pool.execute<RowDataPacket[]>(`SELECT COUNT(DISTINCT r.id) pending_count,COALESCE(SUM(i.line_total),0) pending_value FROM distributor_sales_reports r LEFT JOIN distributor_sales_report_items i ON i.report_id=r.id WHERE r.distributor_id=? AND r.status='SUBMITTED'`,[id]);const [pendingReturns]=await pool.execute<RowDataPacket[]>(`SELECT COUNT(DISTINCT r.id) pending_count,COALESCE(SUM(i.quantity),0) pending_qty FROM distributor_consignment_return_requests r LEFT JOIN distributor_consignment_return_request_items i ON i.request_id=r.id WHERE r.distributor_id=? AND r.status='PENDING'`,[id]);const receivable=Number(sales[0].sales_total)-Number(payments[0].paid_total);return res.json({ok:true,sales_total:Number(sales[0].sales_total),paid_total:Number(payments[0].paid_total),unapplied_total:Number(unapplied[0].unapplied_total),pending_payment:Number(pendingPayment[0].pending_total),pending_payment_count:Number(pendingPayment[0].pending_count),pending_sales_count:Number(pendingSales[0].pending_count),pending_sales_value:Number(pendingSales[0].pending_value),pending_return_count:Number(pendingReturns[0].pending_count),pending_return_qty:Number(pendingReturns[0].pending_qty),receivable});}catch(e){return res.status(500).json({ok:false,message:e instanceof Error?e.message:'Gagal memuat ringkasan.'});}});

